use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let chars: Vec<char> = line.chars().collect()
        let n: int = chars.len() as int
        let mut fields: Vec<string> = []
        let mut cur = ""
        let mut inq = false
        let mut i: int = 0
        while i < n {
            let c = chars[i as usize]
            if inq {
                if c == '"' {
                    if i + 1 < n && chars[(i + 1) as usize] == '"' {
                        cur = cur + "\""
                        i = i + 1
                    } else {
                        inq = false
                    }
                } else {
                    cur = cur + c.to_string()
                }
            } else if c == '"' {
                inq = true
            } else if c == ',' {
                fields.push(cur)
                cur = ""
            } else {
                cur = cur + c.to_string()
            }
            i = i + 1
        }
        fields.push(cur)
        let mut out = ""
        let mut k: int = 0
        let cnt: int = fields.len() as int
        while k < cnt {
            if k > 0 {
                out = out + "|"
            }
            out = out + "[" + fields[k as usize] + "]"
            k = k + 1
        }
        println("${cnt}: ${out}")
    }
}

